context.prefix:
'use client'
import { useRouter, useSearchParams } from 'next/navigation'

interface PaginationProps {
  currentPage: number
  totalPages: number
  baseHref: string
}

export default function Pagination({ currentPage, totalPages, baseHref }: PaginationProps) {

output:
  const router = useRouter()
  const searchParams = useSearchParams()

  // Function to handle pagination click
  const handlePaginationClick = (page: number) => {
    if (currentPage === page) return

    // Update the search params with the new page number
    const updatedSearchParams = new URLSearchParams(searchParams)
    updatedSearchParams.set('page', page.toString())

    // Navigate to the new page with the updated search params
    router.push(`${baseHref}?${updatedSearchParams.toString()}`)
  }

  // Array of pagination links
  const paginationLinks: { label: string, href: string }[] = []

  for (let i = 1; i <= totalPages; i++) {
    paginationLinks.push({
      label: i.toString(),
      href: `${baseHref}?page=${i}`
    })
  }

  return (
    <div className="flex justify-center mt-4">
      {paginationLinks.map((link, index) => (
        <button
          key={index}
          onClick={() => handlePaginationClick(link.label)}
          className={`px-4 py-2 rounded ${currentPage === link.label ? 'bg-blue-500 text-white' : 'bg-gray-300 text-black'} mr-2`}
        >
          {link.label}
        </button>
      ))}
    </div>
  )
}

