    return new NextResponse('Unauthorized', { status: 401 })
  }

  // Parse the request body
  const data = await request.json()

  // Update billing information for the user
  const updatedBillingInfo = await prisma.user.update({
    where: { id: user.id },
    data: {
      billing: {
        ...data,
      },
    },
  })

  if (!updatedBillingInfo) {
    return new NextResponse('Failed to update billing information', { status: 500 })
  }

  // Return the updated billing information
  return NextResponse.json(updatedBillingInfo.billing)
