/**
 * Convert a string to camelCase
 */
export function camelCase(str: string): string {
  // Split the string by spaces and hyphens, then join with camelCase
  return str
    .split(/[\s-]+/)
    .map((word, index) => (index === 0 ? word.toLowerCase() : capitalize(word)))
    .join('');
}

/**
 * Convert a string to snake_case
 */
export function snakeCase(str: string): string {
  // Split the string by spaces and hyphens, then join with underscores
  return str
    .split(/[\s-]+/)
    .map((word) => word.toLowerCase())
    .join('_');
}

/**
 * Convert a string to kebab-case
 */
export function kebabCase(str: string): string {
  // Split the string by spaces and hyphens, then join with dashes
  return str
    .split(/[\s-]+/)
    .map((word) => word.toLowerCase())
    .join('-');
}

/**
 * Convert a string to title case
 */
export function titleCase(str: string): string {
  // Split the string by spaces and hyphens, then capitalize each word
  return str
    .split(/[\s-]+/)
    .map((word) => capitalize(word))
    .join(' ');
}

/**
 * Convert a string to sentence case
 */
export function sentenceCase(str: string): string {
  // Capitalize the first letter of the string and join with spaces
  return capitalize(str.charAt(0)) + str.slice(1).toLowerCase();
}

