    {
      url: '/',
      lastModified: new Date().toISOString(),
      changeFrequency: 'daily',
    },
    ...posts.map((post) => ({
      url: `/posts/${post.id}`,
      lastModified: post.createdAt.toISOString(),
      changeFrequency: 'weekly',
      priority: 0.7,
    })),
  ]
}

